insert into public.products (id, category_id, name, short_description, description, price_kurus, image_url, gallery, color, material, dimensions, detail, badge, stock_quantity, status, sort_order)
values
  ('lighting-nara-dome', 'lighting', 'Nara Seramik Masa Lambası', 'Geniş kubbesi ışığı masaya toplar; kırık beyaz seramik ve ceviz küçük köşelere sıcaklık katar.', 'Yuvarlak seramik gövdesi ve geniş kubbe başlığıyla Nara, defter ya da klavye üzerinde dağılmayan yumuşak bir ışık verir. Ceviz boyun ve taban, açık renkli çalışma masasında doğal bir kontrast oluşturur.', 289000, '/images/lighting/nara-dome-main.png', array['/images/lighting/nara-dome-main.png', '/images/lighting/nara-dome-angle.png']::text[], 'Kırık beyaz / ceviz', 'Sırlı seramik ve ceviz', 'Yükseklik 38 cm · başlık çapı 27 cm · taban çapı 16 cm', 'Işığı aşağı yönlendiren geniş başlık · E14 LED ampul (en çok 8 W, dahil değil) · kablo üzerinde anahtar', null, 20, 'published', 0),
  ('lighting-sera-articulated', 'lighting', 'Sera Mafsallı Masa Lambası', 'İki hareketli kolu ışığı çalışma alanına taşır; ağırlıklı tabanı masada yerini korur.', 'Sera’nın mafsallı çelik kolları, ışığı not alırken yakına veya ekranda çalışırken uzağa yöneltmeyi kolaylaştırır. Kompakt tabanı masada az yer kaplar; adaçayı kaplama ve pirinç eklemler ceviz tonlarıyla uyum sağlar.', 329000, '/images/lighting/sera-articulated-main.png', array['/images/lighting/sera-articulated-main.png', '/images/lighting/sera-articulated-task.png']::text[], 'Adaçayı yeşili', 'Toz boyalı çelik ve pirinç', 'Yükseklik 42–54 cm · yatay erişim 48 cm · taban çapı 17 cm', 'İki mafsallı kol ve ağır taban · E14 LED ampul (en çok 8 W, dahil değil) · kablo üzerinde anahtar', null, 20, 'published', 1),
  ('lighting-toprak-globe', 'lighting', 'Toprak Opal Küre Masa Lambası', 'Opal cam küre ışığı yumuşatır; kiremit seramik gövdesi masada küçük bir vurgu oluşturur.', 'Toprak, opal cam küreden yayılan dağınık ışığı dokulu kiremit seramik gövde ve ceviz ayakla bir araya getirir. Alçak formu monitör yanına veya dar bir komodine sığar; akşamları ortam ışığı olarak kullanılabilir.', 249000, '/images/lighting/toprak-globe-main.png', array['/images/lighting/toprak-globe-main.png', '/images/lighting/toprak-globe-angle.png']::text[], 'Kiremit / opal beyaz', 'Seramik, opal cam ve ceviz', 'Yükseklik 31 cm · küre çapı 18 cm · taban çapı 16 cm', 'Yumuşak ortam ışığı veren opal küre · E14 LED ampul (en çok 6 W, dahil değil) · kablo üzerinde anahtar', null, 20, 'published', 2),
  ('lighting-tala-ceramic', 'lighting', 'Tala Seramik Gövdeli Masa Lambası', 'Yuvarlak seramik gövde, ceviz halkası ve açık renk kumaş başlıkla masaya yumuşak bir ışık verir.', 'Tala, yuvarlak sırlı seramik gövdesini ceviz renkli bir halkayla ve açık renk kumaş başlıkla bir araya getirir. Geniş başlığı ışığı masa yüzeyine yöneltir; dengeli formu komodin veya çalışma masasında kullanılabilir.', 279000, '/images/lighting/tala-ceramic.png', array['/images/lighting/tala-ceramic.png']::text[], 'Kırık beyaz / ceviz', 'Sırlı seramik ve ceviz', 'Yükseklik 39 cm · başlık çapı 28 cm · taban çapı 16 cm', 'Açık renk kumaş başlık · E27 duy · ampul dahil değildir · kablo üzerinde anahtar', null, 18, 'published', 3),
  ('lighting-arin-opal-column', 'lighting', 'Arin Opal Silindir Masa Lambası', 'Uzun opal cam silindir ve ceviz taban, dar alanlarda sade bir ışık noktası oluşturur.', 'Arin''in dikey opal cam silindiri ışığı çevresine yumuşakça yayar. Alçak ceviz tabanı ve ince seramik bileziğiyle monitör yanı ya da küçük bir sehpa üzerinde fazla yer kaplamayan bir form sunar.', 249000, '/images/lighting/arin-opal-column.png', array['/images/lighting/arin-opal-column.png']::text[], 'Kırık beyaz / ceviz', 'Seramik, opal cam ve ceviz', 'Yükseklik 32 cm · cam çapı 11 cm · taban çapı 15 cm', 'Opal cam silindir gövde · E14 duy · ampul dahil değildir · kablo üzerinde anahtar', null, 20, 'published', 4),
  ('lighting-yelken-arc-arm', 'lighting', 'Yelken Yay Kollu Masa Lambası', 'Tek kıvrımlı kolu ve aşağı bakan küçük başlığı ışığı defter ya da klavyeye taşır.', 'Yelken''in adaçayı tonundaki çelik kolu tabandan tek bir yay çizerek yükselir. Başlığı çalışma yüzeyine çevrilebilir; yuvarlak tabanı ve ince silueti masada ayrı bir yerleşim seçeneği sunar.', 319000, '/images/lighting/yelken-arc-arm.png', array['/images/lighting/yelken-arc-arm.png']::text[], 'Adaçayı yeşili', 'Toz boyalı çelik ve pirinç', 'Yükseklik 46 cm · yatay erişim 31 cm · taban çapı 16 cm', 'Tek kıvrımlı çelik kol · E14 duy · ampul dahil değildir · kablo üzerinde anahtar', null, 16, 'published', 5),
  ('lighting-duru-tripod', 'lighting', 'Duru Üç Ayaklı Masa Lambası', 'Küçük seramik başlık ve ceviz ayaklar, komodin veya çalışma köşesine hafif bir siluet katar.', 'Duru''nun üç kısa ceviz ayağı, açık renkli seramik başlığı taşır. Kompakt gövdesi masanın arka köşesinde ya da komodinde kullanılabilir; başlık ışığı aşağı ve çevresine yönlendirir.', 269000, '/images/lighting/duru-tripod-lamp.png', array['/images/lighting/duru-tripod-lamp.png']::text[], 'Kırık beyaz / ceviz', 'Sırlı seramik ve ceviz', 'Yükseklik 34 cm · başlık çapı 19 cm · ayak açıklığı 18 cm', 'Seramik çan biçimli başlık · E14 duy · ampul dahil değildir · kablo üzerinde anahtar', null, 19, 'published', 6),
  ('lighting-pera-clamp', 'lighting', 'Pera Kıskaçlı Çalışma Lambası', 'Masa kenarına tutunan kıskaç taban, çalışma yüzeyinde tabana ayrılan alanı azaltır.', 'Pera, vida mekanizmalı kıskaç tabanı ve iki mafsallı koluyla ışığı çalışma alanına yaklaştırır. Adaçayı boyalı çelik gövdesi masa kenarına bağlanır; başlık not alırken veya klavyede çalışırken farklı yönlere çevrilebilir.', 349000, '/images/lighting/pera-clamp-task-lamp.png', array['/images/lighting/pera-clamp-task-lamp.png']::text[], 'Adaçayı yeşili', 'Toz boyalı çelik ve pirinç', 'Kol erişimi 43 cm · başlık çapı 13 cm · kıskaç açıklığı 4 cm', 'İki mafsallı kol · vida mekanizmalı masa kıskaç tabanı · E14 duy · ampul dahil değildir', null, 14, 'published', 7),
  ('lighting-azra-mushroom', 'lighting', 'Azra Seramik Mantar Masa Lambası', 'Tek parça hissi veren yuvarlak seramik form, masada alçak ve sakin bir ışık noktası oluşturur.', 'Azra''nın kısa gövdesi ve geniş, sığ başlığı mantar biçimli bir siluet oluşturur. Kırık beyaz sır yüzeyi ve tabanındaki ceviz renkli halka, kitaplık veya masa üstündeki diğer ahşap tonlarıyla uyum sağlar.', 289000, '/images/lighting/azra-mushroom-ceramic.png', array['/images/lighting/azra-mushroom-ceramic.png']::text[], 'Kırık beyaz / ceviz', 'Sırlı seramik ve ceviz', 'Yükseklik 27 cm · başlık çapı 25 cm · taban çapı 17 cm', 'Geniş sığ seramik başlık · E14 duy · ampul dahil değildir · kablo üzerinde anahtar', null, 17, 'published', 8),
  ('lighting-ekin-opal-bowl', 'lighting', 'Ekin Opal Kâse Başlıklı Masa Lambası', 'Sığ opal cam başlık, kiremit seramik gövde ve ceviz ayakla küre lambalardan ayrılır.', 'Ekin''de geniş ve sığ opal cam başlık, yivli kiremit seramik gövdenin üzerinde durur. Ceviz ayakla tamamlanan alçak formu, monitör yanı veya yan sehpa için dekoratif bir seçenek sunar.', 299000, '/images/lighting/ekin-opal-bowl-lamp.png', array['/images/lighting/ekin-opal-bowl-lamp.png']::text[], 'Kiremit / opal beyaz', 'Seramik, opal cam ve ceviz', 'Yükseklik 30 cm · başlık çapı 24 cm · taban çapı 15 cm', 'Sığ opal cam başlık · E14 duy · ampul dahil değildir · kablo üzerinde anahtar', null, 15, 'published', 9),
  ('organizers-walnut-monitor-shelf', 'organizers', 'Ceviz masaüstü yükseltici', 'Monitöre yer açan, altında defterleri saklayan alçak raf.', 'Monitörünü göz hizana yaklaştırırken klavye çevresindeki alanı açık bırakır. Raf altındaki bölüm birkaç ince defter ya da klavye için düzenli bir yer sunar.', 249000, '/images/organizers/walnut-desk-shelf.png', array['/images/organizers/walnut-desk-shelf.png']::text[], 'Ceviz', 'Ceviz kaplamalı ahşap', '60 × 24 × 12 cm; raf altı açıklığı 8 cm', '60 cm genişliği standart bir monitör ayağına alan bırakır. 24 cm derinliği masanın ön tarafında çalışma payı tutar; yüzey yaklaşık 15 kg yük için tasarlanmıştır.', null, 20, 'published', 10),
  ('organizers-sage-file-caddy', 'organizers', 'Adaçayı evrak ve kalemlik', 'Dikey dosya bölmeleri ve önde küçük bir eşya tepsisi.', 'Gün içinde elinin altında olmasını istediğin evrakları dik tutar; öndeki sığ tepsi not kâğıtları ve kalemler için ayrılmıştır. Açık bölmeleri içeriklerini bir bakışta görmeni sağlar.', 79000, '/images/organizers/sage-file-organizer.png', array['/images/organizers/sage-file-organizer.png']::text[], 'Adaçayı', 'Toz boyalı çelik', '28 × 13 × 20 cm; ön tepsi derinliği 4 cm', 'A4 evrakı ve ince dosyaları dik konumda tutar. 13 cm derinliği dar masalarda az yer kaplar; metal gövde nemli bezle silinebilir.', null, 20, 'published', 11),
  ('organizers-terracotta-desk-drawers', 'organizers', 'Kiremit çift çekmeceli kutu', 'Masa üstünde küçük araçları göz önünden kaldıran iki çekmece.', 'Şarj kablosu, not kartı ve sık kullandığın küçük kırtasiye parçalarını iki ayrı çekmecede toplar. Üst yüzeyini defter ya da kalemlik için kullanabilirsin.', 129000, '/images/organizers/terracotta-drawer-organizer.png', array['/images/organizers/terracotta-drawer-organizer.png']::text[], 'Kiremit', 'Boyalı MDF', '28 × 23 × 14 cm; her çekmece içi 24 × 19 × 4 cm', 'İki sığ çekmece küçük masa eşyalarını türüne göre ayırır. Ahşap kulplar çekmeceleri kolay açar; nemli bezle silip kuru tutmak yeterlidir.', null, 20, 'published', 12),
  ('organizers-walnut-stacking-trays', 'organizers', 'Ceviz Üçlü Evrak Tepsisi', 'Üst üste dizilebilen üç sığ tepsi, günlük kâğıtları yatay olarak toplar.', 'Üç ayrı tepsiden oluşan bu set, mektupları, not kâğıtlarını ve ince defterleri yatay biçimde bir arada tutar. Tepsiler üst üste kullanılabilir veya masanın farklı noktalarına yan yana yerleştirilebilir.', 139000, '/images/organizers/walnut-stacking-trays.png', array['/images/organizers/walnut-stacking-trays.png']::text[], 'Ceviz', 'Ceviz kaplamalı ahşap', 'Her tepsi 28 × 21 × 5 cm · set toplam yüksekliği 15 cm', 'Üç ayrı açık tepsi · üst üste veya yan yana kullanım · kâğıt ürünler dahil değildir', null, 24, 'published', 13),
  ('organizers-sage-headphone-stand', 'organizers', 'Adaçayı Masaüstü Kulaklık Standı', 'Kavisli metal taşıyıcı ve geniş taban, kulaklık için masada ayrı bir yer ayırır.', 'Mat adaçayı boyalı çelikten üretilen standın kavisli üst bölümü kulaklık bandını taşır; düz tabanı masada küçük eşyalar için ek yüzey bırakır. Açık formu kullanılmadığında da kolayca yer değiştirir.', 99000, '/images/organizers/sage-headphone-stand.png', array['/images/organizers/sage-headphone-stand.png']::text[], 'Adaçayı', 'Toz boyalı çelik', 'Yükseklik 24 cm · taban 14 × 12 cm · üst kıvrım genişliği 5 cm', 'Kavisli metal taşıyıcı ve düz taban · kulaklık dahil değildir', null, 26, 'published', 14),
  ('organizers-terracotta-cable-box', 'organizers', 'Kiremit Kapaklı Kablo Kutusu', 'Ayrı kapağı ve yan açıklıkları, masa üzerindeki kabloları tek noktada toplar.', 'Alçak dikdörtgen kutu, masa üzerindeki kablo fazlasını göz önünden toparlamak için tasarlanmıştır. Kapağı kaldırılabilir; iki kısa kenardaki açıklıklar kabloların kutuya girip çıkmasına yer bırakır.', 89000, '/images/organizers/terracotta-cable-box.png', array['/images/organizers/terracotta-cable-box.png']::text[], 'Kiremit', 'Boyalı MDF', '32 × 14 × 12 cm · iki yanda 3 × 2 cm kablo açıklığı', 'Kaldırılabilir kapak · iki yanda kablo geçiş açıklığı · masaüstü kullanım', null, 22, 'published', 15),
  ('organizers-walnut-bookend-pair', 'organizers', 'Ceviz Çift Kitap Dayanağı', 'İki ahşap dayanak, ince defterleri veya kitapları masanın bir köşesinde dik tutar.', 'Düz tabanlı iki L biçimli dayanak, masa üzerinde kitap ve defterleri yan yana toplamaya yardımcı olur. Ceviz kaplamalı yüzey ve sade dik paneller, raf bulunmayan küçük çalışma köşelerine uygundur.', 119000, '/images/organizers/walnut-bookend-pair.png', array['/images/organizers/walnut-bookend-pair.png']::text[], 'Ceviz', 'Ceviz kaplamalı ahşap', 'Her parça 15 × 12 × 16 cm · set 2 parçadan oluşur', 'Eşleşen iki L biçimli dayanak · görseldeki kitaplar dahil değildir', null, 21, 'published', 16),
  ('organizers-sage-two-tier-letter-rack', 'organizers', 'Adaçayı İki Katlı Mektup Rafı', 'İki yatay metal sepet, mektup ve not kâğıtlarını ayrı katlarda tutar.', 'İki sığ yatay sepetten oluşan açık raf, gün içinde el altında tutulacak mektup ve kâğıtları ayırır. İnce yan ayakları sayesinde dikey dosya bölmelerinden farklı olarak masa üstünde katmanlı bir düzen kurar.', 119000, '/images/organizers/sage-two-tier-letter-rack.png', array['/images/organizers/sage-two-tier-letter-rack.png']::text[], 'Adaçayı', 'Toz boyalı çelik', '28 × 15 × 25 cm · iki sepetin her biri 26 × 14 cm', 'İki açık yatay sepet · mektup ve kâğıtlar dahil değildir', null, 20, 'published', 17),
  ('organizers-terracotta-compartment-tray', 'organizers', 'Kiremit Dört Bölmeli Masa Tepsisi', 'Ayrılabilir bölmeleri, ataş ve not kartı gibi küçük parçaları gruplar.', 'Alçak tepsinin içindeki üç ayırıcı çıkarılıp yeniden yerleştirilebilir; böylece masa üstündeki küçük kırtasiye parçaları için dört gözlü bir düzen elde edilir. Açık yüzeyi içindekileri kolayca görmeyi sağlar.', 99000, '/images/organizers/terracotta-compartment-tray.png', array['/images/organizers/terracotta-compartment-tray.png']::text[], 'Kiremit', 'Boyalı MDF', '24 × 18 × 5 cm · dört bölme', 'Üç çıkarılabilir ayırıcı · içindeki küçük eşyalar dahil değildir', null, 23, 'published', 18),
  ('organizers-walnut-phone-note-dock', 'organizers', 'Ceviz Telefon ve Not Standı', 'Telefon yuvası, ön not oluğu ve yan kalem cebi küçük masa eşyalarını toplar.', 'Ceviz kaplamalı ahşap standın arka yuvası telefonu dik tutar; öndeki dar oluk not kartı için, yandaki cep ise tek bir kalem için ayrılmıştır. Kompakt tabanı masanın köşesine sığar.', 109000, '/images/organizers/walnut-phone-note-dock.png', array['/images/organizers/walnut-phone-note-dock.png']::text[], 'Ceviz', 'Ceviz kaplamalı ahşap', '18 × 12 × 13 cm · telefon yuvası 1.5 cm genişliğinde', 'Telefon yuvası, not oluğu ve yan kalem cebi · telefon, not kartı ve kalem dahil değildir', null, 19, 'published', 19),
  ('stationery-akis-defter', 'stationery', 'Akış A5 Çizgili Defter', 'Günlük notlar için iplik dikişli, 96 sayfalı defter.', 'Toplantı notlarını, günlük planları ve ilk taslakları tek yerde tutmak için taşınabilir A5 boyutunda çizgili bir defter.', 24500, '/images/stationery/akis-defter-cover.png', array['/images/stationery/akis-defter-cover.png', '/images/stationery/akis-defter-open.png']::text[], 'Adaçayı', 'Kâğıt ve karton', 'A5 · 14,8 × 21 cm · 96 sayfa', '90 g/m² çizgili iç kâğıt; mat karton kapak; iplik dikişli sırt.', null, 20, 'published', 20),
  ('stationery-kiremit-not-blok', 'stationery', 'Kiremit Not Bloğu', 'El altında tutulacak kısa notlar için 80 yaprak.', 'Telefon notları, alışveriş listeleri ve hızlı hatırlatmalar için masada kolayca erişilecek kompakt bir not bloğu.', 13500, '/images/stationery/kiremit-not-blok.png', array['/images/stationery/kiremit-not-blok.png', '/images/stationery/kiremit-not-blok-detail.png']::text[], 'Kiremit', 'Kâğıt ve mukavva', '10 × 15 cm · 80 yaprak', 'Boş, 90 g/m² kâğıt yapraklar; kiremit renkli mukavva arkalık.', null, 20, 'published', 21),
  ('stationery-ceviz-kursun-kalem', 'stationery', 'Ceviz Kurşun Kalem Üçlüsü', 'Eskiz ve günlük kullanım için üç adet HB kalem.', 'Kısa çizimler ve kâğıt üzerinde hızlı fikir denemeleri için klasik altıgen gövdeli, üçlü kurşun kalem seti.', 11500, '/images/stationery/ceviz-kalem-set.png', array['/images/stationery/ceviz-kalem-set.png', '/images/stationery/ceviz-kalem-uc-detay.png']::text[], 'Ceviz', 'Ahşap ve grafit', '17,5 cm · 3 adet · HB uç', 'Mat ceviz tonlu altıgen ahşap gövde; sivriltilebilir grafit uç ve silgi başlığı.', null, 20, 'published', 22),
  ('stationery-haftalik-masa-planlayici', 'stationery', 'Haftalık Masa Planlayıcısı', 'Tarihsiz haftalık düzeni ve kısa not alanını 52 yaprakta bir araya getirir.', 'Haftanın işlerini masanın üzerinde görünür tutmak için tasarlanmış tarihsiz bir planlayıcı bloğu. Her yaprakta yedi gün için ayrı bölümler ve haftalık notlar için boş bir alan bulunur.', 28500, '/images/stationery/haftalik-masa-planlayici.png', array['/images/stationery/haftalik-masa-planlayici.png']::text[], 'Adaçayı', 'Kâğıt ve karton', '21 × 29,7 cm · 52 yaprak', 'Tarihsiz haftalık sayfa düzeni; kırık beyaz kâğıt ve adaçayı renkli karton altlık.', null, 18, 'published', 23),
  ('stationery-nokta-kagit-defter', 'stationery', 'Nokta Kâğıt A5 Defter', 'Serbest notlar ve taslaklar için nokta baskılı, 144 sayfalı defter.', 'Çizim, liste ve günlük notları aynı defterde tutmak isteyenler için hafif nokta baskılı iç sayfalar. A5 ölçüsü çantada taşımaya elverişlidir; kapalıyken düz renkli karton kapağı masada sade görünür.', 31500, '/images/stationery/nokta-kagit-defter.png', array['/images/stationery/nokta-kagit-defter.png']::text[], 'Ceviz', 'Kâğıt ve karton', 'A5 · 14,8 × 21 cm · 144 sayfa', 'Nokta baskılı iç kâğıt; mat ceviz tonlu karton kapak.', null, 14, 'published', 24),
  ('stationery-mektup-karti-seti', 'stationery', 'Mektup Kartı ve Zarf Seti', 'Kısa notlar ve küçük tebrikler için sekiz kart ve sekiz zarf.', 'El yazısıyla iletilecek kısa mesajlar için düz yüzeyli katlanır kartlar ve uyumlu zarflardan oluşan bir set. Kartlar boş bırakıldığı için teşekkür, davet veya kişisel not olarak kullanılabilir.', 22000, '/images/stationery/mektup-karti-seti.png', array['/images/stationery/mektup-karti-seti.png']::text[], 'Kiremit', 'Kâğıt ve karton', '8 katlanır kart · 8 zarf · kart: 10 × 15 cm', 'Boş, kırık beyaz kart yüzeyi; kiremit tonlu zarflar ve karton saklama bandı.', null, 21, 'published', 25),
  ('stationery-kraft-cep-dosya-seti', 'stationery', 'Kraft Cep Dosyası Üçlüsü', 'A4 kâğıtları ve çalışma notlarını bir arada tutan üç ince dosya.', 'Ders notlarını, çıktılarını veya üzerinde çalışılan taslakları masada ayrı tutmaya yardımcı olan kraft kâğıt dosyalar. Her dosyanın ön kapağında içerik başlığı elle yazılabilecek boş bir etiket alanı vardır.', 19500, '/images/stationery/kraft-cep-dosya-seti.png', array['/images/stationery/kraft-cep-dosya-seti.png']::text[], 'Ceviz', 'Kâğıt ve mukavva', 'A4 uyumlu · 3 adet · 23 × 32 cm', 'Kraft kâğıt dış yüzey; içte tek cep ve yazılabilir etiket alanı.', null, 16, 'published', 26),
  ('stationery-dalga-ayrac-seti', 'stationery', 'Dalga Kâğıt Ayraç Seti', 'Kitap ve defter sayfalarını işaretlemek için altı renkli kâğıt ayraç.', 'Okurken veya bir defterde sık dönülen bölümleri bulurken kullanılabilecek uzun kâğıt ayraçlar. Her parçada farklı, yumuşak tonlu bir renk bulunur; üst kısımdaki küçük boş alan kısa bir başlık yazmaya uygundur.', 12000, '/images/stationery/dalga-ayrac-seti.png', array['/images/stationery/dalga-ayrac-seti.png']::text[], 'Adaçayı', 'Kâğıt ve karton', '6 adet · her biri 5 × 18 cm', 'Mat yüzeyli kalın kâğıt; yuvarlatılmış köşeler ve üstte yazı alanı.', null, 27, 'published', 27),
  ('stationery-kiremit-indeks-seritleri', 'stationery', 'Kiremit İndeks Şeritleri', 'Kitap ve dosyalarda bölümlere işaret koymak için 80 ince kâğıt şerit.', 'Defter, kitap veya dosyada dönülecek sayfaları küçük renk bloklarıyla ayırmaya yarayan kendinden yapışkanlı kâğıt şeritler. Dört kiremit ve toprak tonuna ayrılan paket, her renkten yirmi şerit içerir.', 9500, '/images/stationery/kiremit-indeks-seritleri.png', array['/images/stationery/kiremit-indeks-seritleri.png']::text[], 'Kiremit', 'Kâğıt ve karton', '80 şerit · her biri 1,5 × 4 cm', 'Dört tonda renkli kâğıt şerit; her renkten 20 adet.', null, 32, 'published', 28),
  ('stationery-pirinclik-sayfa-klipsi', 'stationery', 'Pirinç Tonlu Sayfa Klipsi Seti', 'Açık kitapları ve birkaç sayfayı sabitlemek için üç metal klips.', 'Masa başında açık tutulan kitap, not kâğıdı veya basılı bir taslağın sayfalarını bir arada tutmak için küçük klipsler. İnce profilli üç parça, masa üzerinde kolay bulunmaları için pirinç tonlu metalden üretilmiştir.', 17500, '/images/stationery/pirinc-tonlu-sayfa-klipsi.png', array['/images/stationery/pirinc-tonlu-sayfa-klipsi.png']::text[], 'Ceviz', 'Pirinç tonlu metal', '3 adet · her biri yaklaşık 3 cm', 'Pirinç tonlu kaplamalı metal gövde; set içinde üç farklı boy klips.', null, 24, 'published', 29),
  ('accessories-stoneware-coaster-set', 'accessories', 'Duru Stoneware Bardak Altlığı Seti', 'Dört adet, benekli kırık beyaz sırla elde biçimlendirilmiş seramik altlık.', 'Kupa ve su bardağı altında masayı koruyan, yumuşak kenarlı dört parçalık set. Hafif benekli sır her altlığa kendine özgü bir görünüm verir; mantar taban masa yüzeyini doğrudan seramik temasından ayırır.', 64000, '/images/accessories/stoneware-coasters.png', array['/images/accessories/stoneware-coasters.png', '/images/accessories/stoneware-coasters-detail.png']::text[], 'Kırık beyaz', 'Sırlı stoneware ve mantar', 'Her altlık: 10 × 10 × 0,8 cm; set: 4 adet', 'Mantar tabanlıdır. Nemli bezle silin; elde yıkama veya bulaşık makinesi için uygun değildir.', '4’lü set', 20, 'published', 30),
  ('accessories-filiz-bud-vase', 'accessories', 'Filiz Mini Seramik Vazo', 'Tek dal veya küçük bir demet için dar ağızlı, mat kiremit tonlu vazo.', 'Az yer kaplayan gövdesi küçük masalarda ve raflarda kolayca konumlanır. Dar ağız, birkaç ince dalın dağılmadan durmasına yardımcı olur; iç yüzeyi sırlıdır ve suyla kullanılabilir.', 89000, '/images/accessories/bud-vase.png', array['/images/accessories/bud-vase.png', '/images/accessories/bud-vase-detail.png']::text[], 'Kiremit', 'Mat stoneware, içi sırlı', '12 cm yükseklik × 8 cm en; ağız çapı 2 cm', 'Tek parça seramiktir. Elde yıkayın ve masaya koymadan önce tabanını kurulayın.', null, 20, 'published', 31),
  ('accessories-no04-desk-clock', 'accessories', 'No. 04 Ceviz Masa Saati', 'Kırık beyaz kadranlı, masif ceviz tabanlı kompakt analog saat.', 'Saati ekrana bakmadan takip etmek isteyenler için sade indeksli analog masa saati. Eğik ceviz taban kadranı otururken görünür tutar; küçük gövdesi defter ve klavyenin yanında fazla alan kaplamaz.', 129000, '/images/accessories/walnut-desk-clock.png', array['/images/accessories/walnut-desk-clock.png', '/images/accessories/walnut-desk-clock-detail.png']::text[], 'Ceviz ve kırık beyaz', 'Masif ceviz, cam ve metal mekanizma', '12,5 × 8 × 4 cm', 'Bir adet AA pille çalışır; pil kutuya dahil değildir. Ceviz yüzeyi kuru, yumuşak bezle temizleyin.', null, 20, 'published', 32),
  ('accessories-rota-seramik-kalemlik', 'accessories', 'Rota Seramik Kalemlik', 'Kalemleri ve ince araçları masada bir arada tutan silindirik kalemlik.', 'Gün içinde sık kullanılan kalemleri çalışma alanında el altında tutmak için sade biçimli bir seramik kalemlik. Mat dış yüzey ve sırlı iç yüzey, açık kiremit tonunu tamamlar.', 72000, '/images/accessories/rota-seramik-kalemlik.png', array['/images/accessories/rota-seramik-kalemlik.png']::text[], 'Kiremit', 'Stoneware seramik', '9 cm çap · 10 cm yükseklik', 'Mat dış yüzeyli, içi sırlı seramik gövde.', null, 9, 'published', 33),
  ('accessories-ceviz-telefon-standi', 'accessories', 'Ceviz Masaüstü Telefon Standı', 'Telefonu masada dik konumda tutan kanallı ceviz stand.', 'Görüntülü görüşme veya kısa bir bildirim kontrolü sırasında telefonu çalışma yüzeyinde dik tutmaya yarayan kompakt bir stand. Açılı kanalın altındaki kesik, şarj kablosunun geçmesi için boşluk bırakır; cihaz dahil değildir.', 54000, '/images/accessories/ceviz-telefon-standi.png', array['/images/accessories/ceviz-telefon-standi.png']::text[], 'Ceviz', 'Ceviz ağacı', '8 × 7 × 2 cm · kanal genişliği 1,2 cm', 'Yağlı yüzey bitişli ceviz gövde; arkada kablo geçiş boşluğu.', null, 11, 'published', 34),
  ('accessories-yana-seramik-kitap-dayanaklari', 'accessories', 'Yana Seramik Kitap Dayanakları', 'Raf veya masa üzerinde kitapları dik tutmaya yardımcı olan iki parça.', 'Az sayıda kitabı çalışma masasında veya rafta yan yana düzenlemek için çift olarak kullanılan seramik dayanaklar. İçbükey formu kitapların yanına yerleşir; altındaki mantar yüzey masayla doğrudan seramik temasını ayırır.', 128000, '/images/accessories/yana-seramik-kitap-dayanaklari.png', array['/images/accessories/yana-seramik-kitap-dayanaklari.png']::text[], 'Kırık beyaz', 'Sırlı stoneware ve mantar', 'Her parça: 11 × 12 × 8 cm · 2 adet', 'Kırık beyaz sırlı stoneware gövde; alt yüzeyde mantar taban.', null, 7, 'published', 35),
  ('accessories-yumusak-kece-masa-pedi', 'accessories', 'Yumuşak Keçe Masa Pedi', 'Yazı yazarken defterin altına serilebilen ince keçe yüzey.', 'Defter, küçük klavye veya yazı araçları için masada belirgin bir çalışma alanı oluşturan ince bir yüzey pedi. Yumuşak dokulu keçe, kırık beyaz ve adaçayı tonlarının karışımıyla sade bir masa düzenine uyum sağlar.', 89000, '/images/accessories/kece-masa-pedi.png', array['/images/accessories/kece-masa-pedi.png']::text[], 'Adaçayı', 'Yün karışımlı keçe', '40 × 60 cm · 3 mm kalınlık', 'Yün karışımlı keçe; kenarlar düz kesim.', null, 13, 'published', 36),
  ('accessories-kiremit-yuzey-tepsisi', 'accessories', 'Kiremit Mini Masa Tepsisi', 'Ataş, yüzük ve küçük masa eşyalarını toplamak için sığ seramik tepsi.', 'Masa üzerinde dağılabilecek küçük parçaları tek bir yerde tutmak için yuvarlatılmış köşeli sığ tepsi. Kiremit tonlu yüzey, kalemlik ve defterlerin yanında az yer kaplar.', 46000, '/images/accessories/kiremit-mini-masa-tepsisi.png', array['/images/accessories/kiremit-mini-masa-tepsisi.png']::text[], 'Kiremit', 'Mat stoneware seramik', '14 × 10 × 1,5 cm', 'Mat yüzeyli seramik gövde; alçak kenar ve yuvarlatılmış köşeler.', null, 15, 'published', 37),
  ('accessories-ceviz-kart-tutucu', 'accessories', 'Ceviz Masa Kartı Tutucu', 'İsim kartını, küçük notu veya fotoğrafı dik sergilemek için ceviz blok.', 'Çalışma masasında bir isim kartını, fotoğrafı veya kısa notu görünür tutmak için üstünde ince bir yuva bulunan küçük ahşap blok. Kart yuvası tek bir kâğıt parçasını tutacak genişliktedir.', 26500, '/images/accessories/ceviz-kart-tutucu.png', array['/images/accessories/ceviz-kart-tutucu.png']::text[], 'Ceviz', 'Ceviz ağacı', '10 × 3 × 2 cm · yuva: 2 mm', 'Mat yüzey bitişli masif ceviz blok; üstte tek kart yuvası.', null, 19, 'published', 38),
  ('accessories-minik-seramik-kagit-agirligi', 'accessories', 'Minik Seramik Kâğıt Ağırlığı', 'Açık kâğıt ve hafif notları masa üzerinde sabitlemeye yardımcı olur.', 'Taslak veya not kâğıtlarının köşesine yerleştirilen küçük seramik masa objesi. Yuvarlak formu avuç içinde rahatça tutulur; adaçayı sır üzerindeki hafif benekler her parçanın görünümünü farklılaştırır.', 38500, '/images/accessories/minik-seramik-kagit-agirligi.png', array['/images/accessories/minik-seramik-kagit-agirligi.png']::text[], 'Adaçayı', 'Sırlı stoneware', '6 cm çap · 3 cm yükseklik', 'Adaçayı tonlu, benekli sırlı stoneware gövde.', null, 12, 'published', 39)
